// Port of boltons.dictutils.FrozenDict (repr behavior only).
import { pyDictRepr } from './pyrepr.mjs';

export class FrozenDict {
  constructor(pairs) {
    // A Map matches Python's dict(zip(k, v)): duplicate keys keep their
    // first insertion position while the last occurrence wins the value.
    this._map = new Map(pairs);
  }

  get pairs() {
    return [...this._map.entries()];
  }

  toString() {
    return 'FrozenDict(' + pyDictRepr(this.pairs) + ')';
  }
}

