4	export function pyReprStr(s) {
5	  // Choose quote: single quotes, unless the string contains a single quote
6	  // and no double quote, in which case use double quotes.
7	  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
8	  let out = quote;
9	  for (const ch of s) {
10	    const code = ch.codePointAt(0);
11	    if (ch === '\\') {
12	      out += '\\\\';
13	    } else if (ch === quote) {
14	      out += '\\' + quote;
15	    } else if (ch === '\n') {
16	      out += '\\n';
17	    } else if (ch === '\r') {
18	      out += '\\r';
19	    } else if (ch === '\t') {
20	      out += '\\t';
21	    } else if (code < 32 || code === 127) {
22	      out += '\\x' + code.toString(16).padStart(2, '0');
23	    } else {
24	      out += ch;
25	    }
26	  }
27	  out += quote;
28	  return out;
29	}
